  subgraph CYCLE["Scrum Cycle"]
    direction LR
    P1["1\nPlanning/\nPrioritization"] --> P2["2\nRequirements"] --> P3["3\nDesign/\nAnalysis"] --> P4["4\nImplementation/\nTesting"] --> P5["5\nReview/\nRetrospective"] --> P1
