```mermaid
flowchart LR
  %% ADDIE Model - Circular Flow Diagram (approximated with a circular chain)
  A((Analyze))
  B((Design))
  C((Develop))
  D((Implement))
  E((Evaluate))

  A --> B --> C --> D --> E --> A

  A --- AT["Analyze: Identify learning needs, audience, goals, and constraints."]
  B --- BT["Design: Define objectives, assessment methods, content structure, and learning activities."]
  C --- CT["Develop: Create and assemble content, media, materials, and learning resources."]
  D --- DT["Implement: Deliver the instruction/training and support learners and instructors."]
  E --- ET["Evaluate: Measure effectiveness, gather feedback, and refine for improvement."]

  classDef analyze fill:#f6f39b,stroke:#666,color:#111;
  classDef design fill:#ff4fa3,stroke:#666,color:#fff;
  classDef develop fill:#ff9f43,stroke:#666,color:#111;
  classDef implement fill:#4aa3ff,stroke:#666,color:#fff;
  classDef evaluate fill:#78d26b,stroke:#666,color:#111;
  classDef note fill:#ffffff,stroke:#cfcfcf,color:#111;

  class A analyze;
  class B design;
  class C develop;
  class D implement;
  class E evaluate;

  class AT,BT,CT,DT,ET note;
```

