```mermaid
flowchart TB
  %% B.F. Skinner's Operant Conditioning (grid-style layout)

  subgraph R1[" "]
    direction LR
    PR["Positive Reinforcement<br/><br/>Involves presenting a pleasant stimulus after a desired behaviour, increasing the likelihood that the behaviour will occur again.<br/><br/><b>Example:</b> Giving a child praise for cleaning their room reinforces that positive behaviour."]
    NR["Negative Reinforcement<br/><br/>Involves removing an unpleasant stimulus when a desired behavior occurs, thereby increasing the likelihood of that behaviour.<br/><br/><b>Example:</b> Taking away a child's extra chores when they complete their homework on time."]
  end

  subgraph R2[" "]
    direction LR
    PP["Positive Punishment<br/><br/>Involves administering an unpleasant stimulus to decrease a behaviour.<br/><br/><b>Example:</b> Scolding a child for drawing on the walls aims to reduce that behaviour."]
    NP["Negative Punishment<br/><br/>Involves taking away a pleasant stimulus to decrease a behaviour.<br/><br/><b>Example:</b> Removing a teenager's gaming privileges when they miss their curfew."]
  end

  subgraph R3[" "]
    direction LR
    EX["Extinction<br/><br/>Involves the gradual weakening of a behaviour by stopping reinforcement or punishment. Over time, the behaviour decreases.<br/><br/><b>Example:</b> Ignoring a child's tantrums may ultimately reduce their frequency."]
  end

  %% invisible connectors to keep rows stacked
  PR --- NR
  PP --- NP

  R1 --> R2 --> R3

  classDef pr fill:#b9cbb8,stroke:#5b6b5a,color:#111,stroke-width:1px;
